import assert from "node:assert/strict";
import test from "node:test";
import {
  type AssumedOrder,
  checkProposal,
  type Evidence,
  inferAccents,
  initialInference,
} from "../src/core/inference.ts";
import { initialNotebook, readNotebook, snapshot } from "../src/core/record.ts";
import { inferenceCsv } from "../src/notebook.ts";

test("all 81 partial-evidence/order cases agree with a separate transcription of p. 115", () => {
  // The target triples are transcribed from the four printed endpoints, not generated by experiment().
  const printed = [
    ["h", "z", "d"],
    ["g", "s", "d"],
    ["g", "z", "þ"],
    ["g", "z", "d"],
  ];
  for (const dorsal of ["?", "h", "g"] as const)
    for (const sibilant of ["?", "s", "z"] as const)
      for (const dental of ["?", "þ", "d"] as const)
        for (const order of ["sounds-first", "accent-first", "unknown"] as const) {
          const evidence = { dorsal, sibilant, dental };
          const expected: string[] = [];
          for (const candidateOrder of order === "unknown"
            ? ["sounds-first", "accent-first"]
            : [order]) {
            for (let accent = 0; accent < 4; accent++) {
              const endpoint = printed[candidateOrder === "accent-first" ? 0 : accent];
              assert.ok(endpoint);
              if (
                [dorsal, sibilant, dental].every(
                  (value, index) => value === "?" || value === endpoint[index],
                )
              )
                expected.push(`${candidateOrder}:${accent}`);
            }
          }
          assert.deepEqual(
            inferAccents(evidence, order)
              .filter((item) => item.fits)
              .map((item) => `${item.order}:${item.accent}`),
            expected,
          );
        }
});

test("a compatible proposal can be ambiguous, impossible, or uniquely identified", () => {
  assert.match(
    checkProposal({
      evidence: { dorsal: "h", sibilant: "z", dental: "d" },
      order: "unknown",
      accent: 3,
    }),
    /compatible, but other older accents/,
  );
  assert.match(
    checkProposal({
      evidence: { dorsal: "g", sibilant: "z", dental: "d" },
      order: "unknown",
      accent: 3,
    }),
    /only older accent/,
  );
  assert.match(
    checkProposal({
      evidence: { dorsal: "h", sibilant: "s", dental: "?" },
      order: "sounds-first",
      accent: 0,
    }),
    /excluded.*Second consonant: evidence s, model z/,
  );
  assert.equal(
    inferAccents({ dorsal: "h", sibilant: "s", dental: "?" }, "unknown").filter((item) => item.fits)
      .length,
    0,
  );
});

test("the checked inverse account keeps its own evidence while the draft changes and reopens", () => {
  const state = initialNotebook();
  state.inference = {
    evidence: { dorsal: "g", sibilant: "?", dental: "d" },
    order: "unknown",
    accent: 3,
    submitted: null,
  };
  state.inference.submitted = {
    evidence: { ...state.inference.evidence },
    order: state.inference.order,
    accent: state.inference.accent,
  };
  const captured = snapshot(state);
  state.inference.evidence.dorsal = "h";
  state.inference.order = "accent-first";
  const reopened = readNotebook(JSON.stringify(state));
  assert.deepEqual(reopened.inference.submitted, captured.inference.submitted);
  assert.equal(reopened.inference.evidence.dorsal, "h");
  const csv = inferenceCsv(reopened);
  assert.match(csv, /"current-evidence","h","\?","d","accent-first"/);
  assert.match(csv, /"checked-proposal","g","\?","d","unknown"/);
});

test("earlier notebooks receive an empty inverse account; invalid new evidence is rejected", () => {
  const old: Record<string, unknown> = { ...initialNotebook() };
  delete old.inference;
  assert.deepEqual(readNotebook(JSON.stringify(old)).inference, initialInference());
  for (const bad of [
    { ...initialInference(), accent: 4 },
    { ...initialInference(), order: "not-known" },
    { ...initialInference(), evidence: { dorsal: "x", sibilant: "z", dental: "d" } },
    {
      ...initialInference(),
      submitted: {
        evidence: { dorsal: "h", sibilant: "z", dental: "d" },
        order: "unknown",
        accent: -1,
      },
    },
  ]) {
    assert.throws(() => readNotebook(JSON.stringify({ ...old, inference: bad })));
  }
  const evidence: Evidence = { dorsal: "?", sibilant: "?", dental: "?" };
  const order: AssumedOrder = "unknown";
  assert.equal(inferAccents(evidence, order).filter((item) => item.fits).length, 8);
});
